package main

import (
	"bufio"
	"fmt"
	"os"
)

func parseInts(s string) []int {
	nums := make([]int, 0)
	value := 0
	inNumber := false

	for i := 0; i <= len(s); i++ {
		if i < len(s) && s[i] >= '0' && s[i] <= '9' {
			value = value*10 + int(s[i]-'0')
			inNumber = true
		} else if inNumber {
			nums = append(nums, value)
			value = 0
			inNumber = false
		}
	}
	return nums
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Buffer(make([]byte, 1024), 1<<20)

	arrays := make([][]int, 0, 2)
	for scanner.Scan() && len(arrays) < 2 {
		values := parseInts(scanner.Text())
		if len(values) > 0 {
			arrays = append(arrays, values)
		}
	}

	if len(arrays) < 2 {
		return
	}

	cost, times := arrays[0], arrays[1]
	n := len(cost)
	if len(times) < n {
		n = len(times)
	}

	const inf = int(^uint(0)>>1) / 4
	dp := make([]int, n+1)
	for i := 1; i <= n; i++ {
		dp[i] = inf
	}

	for i := 0; i < n; i++ {
		next := make([]int, n+1)
		copy(next, dp)

		for painted := 0; painted <= n; painted++ {
			if dp[painted] == inf {
				continue
			}

			newPainted := painted + times[i] + 1
			if newPainted > n {
				newPainted = n
			}

			if candidate := dp[painted] + cost[i]; candidate < next[newPainted] {
				next[newPainted] = candidate
			}
		}
		dp = next
	}

	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()
	fmt.Fprintln(writer, dp[n])
}
