	var answer int64

	for left := 0; left < len(nums); left++ {
		present := make(map[int]bool)
		imbalance := 0

		for right := left; right < len(nums); right++ {
			x := nums[right]

			if !present[x] {
				if len(present) > 0 {
					imbalance++
					if present[x-1] {
						imbalance--
					}
					if present[x+1] {
						imbalance--
					}
				}
				present[x] = true
			}

			answer += int64(imbalance)
		}
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, answer)
