import (
	"bufio"
	"fmt"
	"io"
	"os"
	"strconv"
	"strings"
)

func main() {
	data, _ := io.ReadAll(os.Stdin)
	tokens := strings.Fields(string(data))
	if len(tokens) == 0 {
		return
	}

	words := tokens
	if n, err := strconv.Atoi(tokens[0]); err == nil {
		if n >= 0 && len(tokens) >= n+1 {
			words = tokens[1 : n+1]
		}
	}
	if len(words) == 0 {
		fmt.Println(0)
		return
	}

	const inf = int(1e9)
	var dp [26][26]int
	for i := 0; i < 26; i++ {
		for j := 0; j < 26; j++ {
			dp[i][j] = inf
		}
	}

	first := int(words[0][0] - 'a')
	last := int(words[0][len(words[0])-1] - 'a')
	dp[first][last] = len(words[0])

	for i := 1; i < len(words); i++ {
		word := words[i]
		wFirst := int(word[0] - 'a')
		wLast := int(word[len(word)-1] - 'a')
		wLen := len(word)

		var next [26][26]int
		for a := 0; a < 26; a++ {
			for b := 0; b < 26; b++ {
				next[a][b] = inf
			}
		}

		for left := 0; left < 26; left++ {
			for right := 0; right < 26; right++ {
				if dp[left][right] == inf {
					continue
				}

				// join(current, word)
				cost := dp[left][right] + wLen
				if right == wFirst {
					cost--
				}
				if cost < next[left][wLast] {
					next[left][wLast] = cost
				}

				// join(word, current)
				cost = dp[left][right] + wLen
				if wLast == left {
					cost--
				}
				if cost < next[wFirst][right] {
					next[wFirst][right] = cost
				}
			}
		}

		dp = next
	}

	answer := inf
	for i := 0; i < 26; i++ {
		for j := 0; j < 26; j++ {
			if dp[i][j] < answer {
				answer = dp[i][j]
			}
		}
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, answer)
}
