package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
)

type pair struct {
	a, b int64
}

func parseInts(s string) []int64 {
	var result []int64
	for i := 0; i < len(s); {
		for i < len(s) && (s[i] < '0' || s[i] > '9') && s[i] != '-' {
			i++
		}
		if i >= len(s) {
			break
		}

		sign := int64(1)
		if s[i] == '-' {
			sign = -1
			i++
		}

		var value int64
		hasDigit := false
		for i < len(s) && s[i] >= '0' && s[i] <= '9' {
			value = value*10 + int64(s[i]-'0')
			i++
			hasDigit = true
		}
		if hasDigit {
			result = append(result, sign*value)
		}
	}
	return result
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Buffer(make([]byte, 1024), 1<<20)

	var lines [][]int64
	for scanner.Scan() {
		values := parseInts(scanner.Text())
		if len(values) > 0 {
			lines = append(lines, values)
		}
	}

	if len(lines) < 3 || len(lines[0]) != len(lines[1]) {
		return
	}

	nums1 := lines[0]
	nums2 := lines[1]
	x := lines[2][0]
	n := len(nums1)

	pairs := make([]pair, n)
	var sum1, sum2 int64
	for i := 0; i < n; i++ {
		pairs[i] = pair{nums1[i], nums2[i]}
		sum1 += nums1[i]
		sum2 += nums2[i]
	}

	sort.Slice(pairs, func(i, j int) bool {
		return pairs[i].b < pairs[j].b
	})

	dp := make([]int64, n+1)
	for i, p := range pairs {
		for operations := i + 1; operations >= 1; operations-- {
			reduction := dp[operations-1] + p.a + int64(operations)*p.b
			if reduction > dp[operations] {
				dp[operations] = reduction
			}
		}
	}

	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()

	for time := 0; time <= n; time++ {
		total := sum1 + int64(time)*sum2 - dp[time]
		if total <= x {
			fmt.Fprintln(writer, time)
			return
		}
	}

	fmt.Fprintln(writer, -1)
}
