		if data[i] < '0' || data[i] > '9' {
			i++
			continue
		}

		var value int64
		for i < len(data) && data[i] >= '0' && data[i] <= '9' {
			value = value*10 + int64(data[i]-'0')
			i++
		}
		values = append(values, value)
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	if len(values) < 2 {
		fmt.Fprintln(out, -1)
		return
	}

	target := values[len(values)-1]
	nums := values[:len(values)-1]

	var total int64
	count := make([]int64, 64)

	for _, num := range nums {
		total += num
		for bit := 0; bit < len(count); bit++ {
			if num == int64(1)<<bit {
				count[bit]++
				break
			}
		}
	}

	if total < target {
		fmt.Fprintln(out, -1)
		return
	}

	operations := 0

	for bit := 0; bit <= 30; bit++ {
		if target&(int64(1)<<bit) != 0 {
			if count[bit] == 0 {
				higher := bit + 1
				for higher < len(count) && count[higher] == 0 {
					higher++
				}

				if higher == len(count) {
					fmt.Fprintln(out, -1)
					return
				}

				for higher > bit {
					count[higher]--
					count[higher-1] += 2
					higher--
					operations++
				}
			}
			count[bit]--
		}

		count[bit+1] += count[bit] / 2
	}

	fmt.Fprintln(out, operations)
}
