import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

const mod int64 = 12345

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Buffer(make([]byte, 1024), 2*1024*1024)

	n := 0
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line == "" {
			continue
		}
		n, _ = strconv.Atoi(line)
		break
	}

	grid := make([][]int64, 0, n)
	values := make([]int64, 0)

	for len(grid) < n && scanner.Scan() {
		fields := strings.Fields(scanner.Text())
		if len(fields) == 0 {
			continue
		}

		row := make([]int64, len(fields))
		for i, field := range fields {
			value, _ := strconv.ParseInt(field, 10, 64)
			value %= mod
			row[i] = value
			values = append(values, value)
		}
		grid = append(grid, row)
	}

	result := make([]int64, len(values))

	prefix := int64(1)
	for i, value := range values {
		result[i] = prefix
		prefix = (prefix * value) % mod
	}

	suffix := int64(1)
	for i := len(values) - 1; i >= 0; i-- {
		result[i] = (result[i] * suffix) % mod
		suffix = (suffix * values[i]) % mod
	}

	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()

	fmt.Fprintln(writer, n)

	index := 0
	for _, row := range grid {
		for j := range row {
			if j > 0 {
				fmt.Fprint(writer, " ")
			}
			fmt.Fprint(writer, result[index])
			index++
		}
		fmt.Fprintln(writer)
	}
}
