		nums[i], _ = strconv.ParseInt(field, 10, 64)
	}
	return nums
}

func operations(nums1, nums2 []int64, swapLast bool) int {
	n := len(nums1)
	max1, max2 := nums1[n-1], nums2[n-1]
	count := 0

	if swapLast {
		max1, max2 = max2, max1
		count = 1
	}

	for i := 0; i < n-1; i++ {
		withoutSwap := nums1[i] <= max1 && nums2[i] <= max2
		withSwap := nums2[i] <= max1 && nums1[i] <= max2

		if !withoutSwap && !withSwap {
			return -1
		}
		if !withoutSwap {
			count++
		}
	}

	return count
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Buffer(make([]byte, 1024), 1024*1024)

	var lines []string
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line != "" {
			lines = append(lines, line)
		}
	}

	if len(lines) < 2 {
		return
	}

	nums1 := parseLine(lines[0])
	nums2 := parseLine(lines[1])
	if len(nums1) == 0 || len(nums1) != len(nums2) {
		fmt.Println(-1)
		return
	}

	answer1 := operations(nums1, nums2, false)
	answer2 := operations(nums1, nums2, true)

	answer := -1
	if answer1 != -1 {
		answer = answer1
	}
	if answer2 != -1 && (answer == -1 || answer2 < answer) {
		answer = answer2
	}

	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()
	fmt.Fprintln(writer, answer)
}
