func countSegment(word string, start, end, k int) int64 {
	length := end - start
	var result int64

	for distinct := 1; distinct <= 26 && distinct*k <= length; distinct++ {
		windowSize := distinct * k
		var counts [26]int
		exactK := 0

		add := func(index int) {
			c := int(word[index] - 'a')
			if counts[c] == k {
				exactK--
			}
			counts[c]++
			if counts[c] == k {
				exactK++
			}
		}

		remove := func(index int) {
			c := int(word[index] - 'a')
			if counts[c] == k {
				exactK--
			}
			counts[c]--
			if counts[c] == k {
				exactK++
			}
		}

		for i := start; i < start+windowSize; i++ {
			add(i)
		}
		if exactK == distinct {
			result++
		}

		for right := start + windowSize; right < end; right++ {
			remove(right - windowSize)
			add(right)
			if exactK == distinct {
				result++
			}
		}
	}

	return result
}

func main() {
	in := bufio.NewReader(os.Stdin)
	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	var word string
	var k int
	if _, err := fmt.Fscan(in, &word, &k); err != nil {
		return
	}

	var answer int64
	segmentStart := 0

	for i := 1; i <= len(word); i++ {
		if i == len(word) || abs(int(word[i])-int(word[i-1])) > 2 {
			answer += countSegment(word, segmentStart, i, k)
			segmentStart = i
		}
	}

	fmt.Fprintln(out, answer)
}

func abs(x int) int {
	if x < 0 {
		return -x
	}
	return x
}
