			&variables[i][0],
			&variables[i][1],
			&variables[i][2],
			&variables[i][3],
		)
	}

	var target int64
	fmt.Fscan(in, &target)

	first := true
	for i, v := range variables {
		inner := modPow(v[0], v[1], 10)
		value := modPow(inner, v[2], v[3])
		if value == target {
