func main() {
	in := bufio.NewReader(os.Stdin)

	var x, y int
	fmt.Fscan(in, &x, &y)

	memo := make(map[int]int)

	var solve func(int) int
	solve = func(n int) int {
		if n <= y {
			return y - n
		}
		if result, ok := memo[n]; ok {
			return result
		}

		best := n - y

		for _, divisor := range []int{5, 11} {
			remainder := n % divisor

			// Decrement to the nearest lower multiple, then divide.
			candidate := remainder + 1 + solve(n/divisor)
			if candidate < best {
				best = candidate
			}

			// Increment to the nearest upper multiple, then divide.
			increments := (divisor - remainder) % divisor
			candidate = increments + 1 + solve((n+increments)/divisor)
			if candidate < best {
				best = candidate
			}
		}

		memo[n] = best
		return best
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	fmt.Fprintln(out, solve(x))
}
