const mod int64 = 1_000_000_007

func main() {
	in := bufio.NewReader(os.Stdin)

	var zero, one, limit int
	if _, err := fmt.Fscan(in, &zero, &one, &limit); err != nil {
		return
	}

	endZero := make([][]int64, zero+1)
	endOne := make([][]int64, zero+1)
	for i := 0; i <= zero; i++ {
		endZero[i] = make([]int64, one+1)
		endOne[i] = make([]int64, one+1)
	}

	for i := 1; i <= zero && i <= limit; i++ {
		endZero[i][0] = 1
	}
	for j := 1; j <= one && j <= limit; j++ {
		endOne[0][j] = 1
	}

	for i := 1; i <= zero; i++ {
		for j := 1; j <= one; j++ {
			for run := 1; run <= limit && run <= i; run++ {
				endZero[i][j] += endOne[i-run][j]
				if endZero[i][j] >= mod {
					endZero[i][j] -= mod
				}
			}

			for run := 1; run <= limit && run <= j; run++ {
				endOne[i][j] += endZero[i][j-run]
				if endOne[i][j] >= mod {
					endOne[i][j] -= mod
				}
			}
		}
	}

	answer := (endZero[zero][one] + endOne[zero][one]) % mod

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, answer)
}
