func main() {
	in := bufio.NewReader(os.Stdin)

	var power []int64
	for {
		var x int64
		if _, err := fmt.Fscan(in, &x); err != nil {
			break
		}
		power = append(power, x)
	}

	if len(power) == 0 {
		return
	}

	sort.Slice(power, func(i, j int) bool {
		return power[i] < power[j]
	})

	values := make([]int64, 0)
	damage := make([]int64, 0)

	for i := 0; i < len(power); {
		j := i + 1
		for j < len(power) && power[j] == power[i] {
			j++
		}
		values = append(values, power[i])
		damage = append(damage, power[i]*int64(j-i))
		i = j
	}

	// dp[i] is the maximum damage using the first i distinct values.
	dp := make([]int64, len(values)+1)

	for i, value := range values {
		// Find how many earlier values are strictly less than value - 2.
		compatible := sort.Search(i, func(j int) bool {
			return values[j] >= value-2
		})

		take := damage[i] + dp[compatible]
		skip := dp[i]

		if take > skip {
			dp[i+1] = take
		} else {
			dp[i+1] = skip
		}
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, dp[len(values)])
}
