package main

import (
	"bufio"
	"fmt"
	"os"
)

func treeDiameter(edgeCount int, in *bufio.Reader) int {
	n := edgeCount + 1
	adj := make([][]int, n)

	for i := 0; i < edgeCount; i++ {
		var u, v int
		fmt.Fscan(in, &u, &v)
		adj[u] = append(adj[u], v)
		adj[v] = append(adj[v], u)
	}

	bfs := func(start int) (int, int) {
		dist := make([]int, n)
		for i := range dist {
			dist[i] = -1
		}

		queue := make([]int, n)
		head, tail := 0, 1
		queue[0] = start
		dist[start] = 0
		farthest := start

		for head < tail {
			u := queue[head]
			head++

			if dist[u] > dist[farthest] {
				farthest = u
			}

			for _, v := range adj[u] {
				if dist[v] == -1 {
					dist[v] = dist[u] + 1
					queue[tail] = v
					tail++
				}
			}
		}

		return farthest, dist[farthest]
	}

	endpoint, _ := bfs(0)
	_, diameter := bfs(endpoint)
	return diameter
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var edgeCount1 int
	if _, err := fmt.Fscan(in, &edgeCount1); err != nil {
		return
	}
	diameter1 := treeDiameter(edgeCount1, in)

	var edgeCount2 int
	fmt.Fscan(in, &edgeCount2)
	diameter2 := treeDiameter(edgeCount2, in)

	mergedDiameter := (diameter1+1)/2 + (diameter2+1)/2 + 1
	answer := mergedDiameter
	if diameter1 > answer {
		answer = diameter1
	}
	if diameter2 > answer {
		answer = diameter2
	}

	fmt.Fprintln(out, answer)
}
