```go
package main

import (
	"bufio"
	"fmt"
	"os"
)

type Circle struct {
	x, y, r int64
}

type DSU struct {
	parent []int
	rank   []int
}

func NewDSU(n int) *DSU {
	parent := make([]int, n)
	rank := make([]int, n)
	for i := range parent {
		parent[i] = i
	}
	return &DSU{parent: parent, rank: rank}
}

func (d *DSU) Find(x int) int {
	if d.parent[x] != x {
		d.parent[x] = d.Find(d.parent[x])
	}
	return d.parent[x]
}

func (d *DSU) Union(a, b int) {
	ra, rb := d.Find(a), d.Find(b)
	if ra == rb {
		return
	}
	if d.rank[ra] < d.rank[rb] {
		ra, rb = rb, ra
	}
	d.parent[rb] = ra
	if d.rank[ra] == d.rank[rb] {
		d.rank[ra]++
	}
}

func sq(x int64) int64 {
	return x * x
}

func touchesVerticalSegment(c Circle, xLine, maxY int64) bool {
	dx := c.x - xLine
	if dx < 0 {
		dx = -dx
	}

	var dy int64
	if c.y > maxY {
		dy = c.y - maxY
	}
	return sq(dx)+sq(dy) <= sq(c.r)
}

func touchesHorizontalSegment(c Circle, yLine, maxX int64) bool {
	dy := c.y - yLine
	if dy < 0 {
		dy = -dy
	}

	var dx int64
	if c.x > maxX {
		dx = c.x - maxX
	}
	return sq(dx)+sq(dy) <= sq(c.r)
}

func main() {
	in := bufio.NewReader(os.Stdin)

	var xCorner, yCorner int64
	var n int
	if _, err := fmt.Fscan(in, &xCorner); err != nil {
		return
	}
	fmt.Fscan(in, &yCorner)
	fmt.Fscan(in, &n)

	circles := make([]Circle, n)
	for i := range circles {
		fmt.Fscan(in, &circles[i].x, &circles[i].y, &circles[i].r)
	}

	constraintsBlocked := false
	for _, c := range circles {
		// The path cannot start or end on or inside a circle.
		if sq(c.x)+sq(c.y) <= sq(c.r) {
			constraintsBlocked = true
			break
		}
		dx := c.x - xCorner
		dy := c.y - yCorner
		if sq(dx)+sq(dy) <= sq(c.r) {
			constraintsBlocked = true
			break
		}
	}

	if constraintsBlocked {
		out := bufio.NewWriter(os.Stdout)
		fmt.Fprintln(out, "false")
		out.Flush()
		return
	}

	// A connection between the left/top boundary group and the
	// bottom/right boundary group separates the two target corners.
	leftTop := n
	bottomRight := n + 1
	dsu := NewDSU(n + 2)

	for i, c := range circles {
		touchesLeft := touchesVerticalSegment(c, 0, yCorner)
		touchesTop := touchesHorizontalSegment(c, yCorner, xCorner)
		touchesRight := touchesVerticalSegment(c, xCorner, yCorner)
		touchesBottom := touchesHorizontalSegment(c, 0, xCorner)

		if touchesLeft || touchesTop {
			dsu.Union(i, leftTop)
		}
		if touchesBottom || touchesRight {
			dsu.Union(i, bottomRight)
		}
	}

	for i := 0; i < n; i++ {
		for j := i + 1; j < n; j++ {
			a, b := circles[i], circles[j]
			dx := a.x - b.x
			dy := a.y - b.y
			radiusSum := a.r + b.r

			if sq(dx)+sq(dy) > sq(radiusSum) {
				continue
			}

			// The weighted point lies in both disks when they overlap.
			// Requiring it to be strictly within the rectangle avoids
			// connecting circles whose relevant overlap is only outside.
			weightedX := a.x*b.r + b.x*a.r
			weightedY := a.y*b.r + b.y*a.r
			if weightedX < xCorner*radiusSum &&
				weightedY < yCorner*radiusSum {
				dsu.Union(i, j)
			}
		}
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	if dsu.Find(leftTop) == dsu.Find(bottomRight) {
		fmt.Fprintln(out, "false")
	} else {
		fmt.Fprintln(out, "true")
	}
}
