package main

import (
	"bufio"
	"fmt"
	"os"
)

func triangle(t int) int64 {
	if t < 0 {
		return 0
	}
	x := int64(t)
	return (x + 1) * (x + 2) / 2
}

func countSumAtMost(left, right, limit int) int64 {
	if limit < 0 {
		return 0
	}
	return triangle(limit) -
		triangle(limit-left) -
		triangle(limit-right) +
		triangle(limit-left-right)
}

func main() {
	in := bufio.NewReader(os.Stdin)

	var s string
	if _, err := fmt.Fscan(in, &s); err != nil {
		return
	}

	n := len(s)
	zeros := make([]int, 0)
	var answer int64

	// Count substrings containing no zeros.
	onesRun := 0
	for i := 0; i < n; i++ {
		if s[i] == '1' {
			onesRun++
		} else {
			answer += int64(onesRun) * int64(onesRun+1) / 2
			onesRun = 0
			zeros = append(zeros, i)
		}
	}
	answer += int64(onesRun) * int64(onesRun+1) / 2

	// Count substrings containing exactly k zeros.
	for k := 1; k*k+k <= n; k++ {
		for first := 0; first+k-1 < len(zeros); first++ {
			last := first + k - 1

			previousZero := -1
			if first > 0 {
				previousZero = zeros[first-1]
			}

			nextZero := n
			if last+1 < len(zeros) {
				nextZero = zeros[last+1]
			}

			leftChoices := zeros[first] - previousZero
			rightChoices := nextZero - zeros[last]
			baseLength := zeros[last] - zeros[first] + 1
			requiredExtension := k*k + k - baseLength

			totalChoices := int64(leftChoices) * int64(rightChoices)
			invalidChoices := countSumAtMost(
				leftChoices,
				rightChoices,
				requiredExtension-1,
			)
			answer += totalChoices - invalidChoices
		}
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, answer)
}
