func main() {
	in := bufio.NewReader(os.Stdin)

	var mountainHeight int64
	if _, err := fmt.Fscan(in, &mountainHeight); err != nil {
		return
	}

	var workerTimes []int64
	var t int64
	for {
		if _, err := fmt.Fscan(in, &t); err != nil {
			break
		}
		workerTimes = append(workerTimes, t)
	}

	minWorkerTime := workerTimes[0]
	for _, w := range workerTimes[1:] {
		if w < minWorkerTime {
			minWorkerTime = w
		}
	}

	canFinish := func(seconds int64) bool {
		var total int64

		for _, w := range workerTimes {
			low, high := int64(0), mountainHeight
			for low < high {
				mid := low + (high-low+1)/2
				required := w * mid * (mid + 1) / 2
				if required <= seconds {
					low = mid
				} else {
					high = mid - 1
				}
			}

			total += low
			if total >= mountainHeight {
				return true
			}
		}
		return false
	}

	left := int64(0)
	right := minWorkerTime * mountainHeight * (mountainHeight + 1) / 2

	for left < right {
		mid := left + (right-left)/2
		if canFinish(mid) {
			right = mid
		} else {
			left = mid + 1
		}
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, left)
}
