package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

func parseLine(line string) []int64 {
	fields := strings.FieldsFunc(line, func(r rune) bool {
		return r < '0' || r > '9'
	})

	nums := make([]int64, 0, len(fields))
	for _, field := range fields {
		if field == "" {
			continue
		}
		value, err := strconv.ParseInt(field, 10, 64)
		if err == nil {
			nums = append(nums, value)
		}
	}
	return nums
}

func max(values ...int64) int64 {
	result := values[0]
	for _, value := range values[1:] {
		if value > result {
			result = value
		}
	}
	return result
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Buffer(make([]byte, 1024), 2*1024*1024)

	var arrays [][]int64
	for scanner.Scan() {
		nums := parseLine(scanner.Text())
		if len(nums) > 0 {
			arrays = append(arrays, nums)
		}
	}

	if len(arrays) < 2 || len(arrays[0]) == 0 {
		return
	}

	a, b := arrays[0], arrays[1]
	n := len(a)
	if len(b) < n {
		n = len(b)
	}

	drinkA := a[0]
	drinkB := b[0]
	rest := int64(0)

	for i := 1; i < n; i++ {
		nextA := max(drinkA, rest) + a[i]
		nextB := max(drinkB, rest) + b[i]
		nextRest := max(drinkA, drinkB, rest)

		drinkA, drinkB, rest = nextA, nextB, nextRest
	}

	writer := bufio.NewWriter(os.Stdout)
