package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
)

type Point struct {
	x, y int64
	id   int
}

type Fenwick struct {
	tree []int
}

func (f *Fenwick) update(i, value int) {
	for i < len(f.tree) {
		if value > f.tree[i] {
			f.tree[i] = value
		}
		i += i & -i
	}
}

func (f *Fenwick) query(i int) int {
	result := 0
	for i > 0 {
		if f.tree[i] > result {
			result = f.tree[i]
		}
		i -= i & -i
	}
	return result
}

// longestEndingAt returns the longest strictly increasing chain ending at target.
func longestEndingAt(points []Point, target int) int {
	sortedPoints := append([]Point(nil), points...)
	sort.Slice(sortedPoints, func(i, j int) bool {
		if sortedPoints[i].x != sortedPoints[j].x {
			return sortedPoints[i].x < sortedPoints[j].x
		}
		return sortedPoints[i].y < sortedPoints[j].y
	})

	ys := make([]int64, len(points))
	for i, p := range points {
		ys[i] = p.y
	}
	sort.Slice(ys, func(i, j int) bool { return ys[i] < ys[j] })

	uniqueY := ys[:0]
	for _, y := range ys {
		if len(uniqueY) == 0 || uniqueY[len(uniqueY)-1] != y {
			uniqueY = append(uniqueY, y)
		}
	}

	fenwick := Fenwick{tree: make([]int, len(uniqueY)+1)}
	answer := 1

	for start := 0; start < len(sortedPoints); {
		end := start
		for end < len(sortedPoints) && sortedPoints[end].x == sortedPoints[start].x {
			end++
		}

		values := make([]int, end-start)
		ranks := make([]int, end-start)

		// Query all points with the same x before updating, ensuring strict x.
		for i := start; i < end; i++ {
			rank := sort.Search(len(uniqueY), func(j int) bool {
				return uniqueY[j] >= sortedPoints[i].y
			})
			values[i-start] = fenwick.query(rank) + 1
			ranks[i-start] = rank + 1

			if sortedPoints[i].id == target {
				answer = values[i-start]
			}
		}

		for i := start; i < end; i++ {
			fenwick.update(ranks[i-start], values[i-start])
		}
		start = end
	}

	return answer
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var n int
	if _, err := fmt.Fscan(in, &n); err != nil {
		return
	}

	points := make([]Point, n)
	for i := 0; i < n; i++ {
		fmt.Fscan(in, &points[i].x, &points[i].y)
		points[i].id = i
	}

	var k int
	fmt.Fscan(in, &k)

	leftLength := longestEndingAt(points, k)

	reversed := make([]Point, n)
	for i, p := range points {
		reversed[i] = Point{x: -p.x, y: -p.y, id: p.id}
	}
	rightLength := longestEndingAt(reversed, k)

	fmt.Fprintln(out, leftLength+rightLength-1)
}
