type Edge struct {
	to   string
	rate float64
}

func readGraph(in *bufio.Reader) map[string][]Edge {
	var n int
	fmt.Fscan(in, &n)

	from := make([]string, n)
	to := make([]string, n)
	for i := 0; i < n; i++ {
		fmt.Fscan(in, &from[i], &to[i])
	}

	rates := make([]float64, n)
	for i := 0; i < n; i++ {
		fmt.Fscan(in, &rates[i])
	}

	graph := make(map[string][]Edge)
	for i := 0; i < n; i++ {
		graph[from[i]] = append(graph[from[i]], Edge{to[i], rates[i]})
		graph[to[i]] = append(graph[to[i]], Edge{from[i], 1.0 / rates[i]})
	}
	return graph
}

func conversionRates(start string, graph map[string][]Edge) map[string]float64 {
	values := map[string]float64{start: 1.0}
	queue := []string{start}

	for len(queue) > 0 {
		currency := queue[0]
		queue = queue[1:]

		for _, edge := range graph[currency] {
			if _, visited := values[edge.to]; visited {
				continue
			}
			values[edge.to] = values[currency] * edge.rate
			queue = append(queue, edge.to)
		}
	}
	return values
}

func main() {
	in := bufio.NewReader(os.Stdin)

	var initialCurrency string
	if _, err := fmt.Fscan(in, &initialCurrency); err != nil {
		return
	}

	day1Graph := readGraph(in)
	day2Graph := readGraph(in)

	day1Values := conversionRates(initialCurrency, day1Graph)
	day2Values := conversionRates(initialCurrency, day2Graph)

	best := 1.0
	for currency, day1Amount := range day1Values {
		if initialToCurrency, reachable := day2Values[currency]; reachable {
			result := day1Amount / initialToCurrency
			if result > best {
				best = result
			}
		}
	}

	output := strconv.FormatFloat(best, 'f', 10, 64)
	output = strings.TrimRight(output, "0")
	output = strings.TrimRight(output, ".")
	if !strings.Contains(output, ".") {
		output += ".0"
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, output)
}
