package main

import (
	"bufio"
	"container/heap"
	"fmt"
	"os"
	"strconv"
	"strings"
)

type State struct {
	time int64
	pos  int
}

type PriorityQueue []State

func (pq PriorityQueue) Len() int            { return len(pq) }
func (pq PriorityQueue) Less(i, j int) bool  { return pq[i].time < pq[j].time }
func (pq PriorityQueue) Swap(i, j int)       { pq[i], pq[j] = pq[j], pq[i] }
func (pq *PriorityQueue) Push(x interface{}) { *pq = append(*pq, x.(State)) }
func (pq *PriorityQueue) Pop() interface{} {
	old := *pq
	n := len(old)
	item := old[n-1]
	*pq = old[:n-1]
	return item
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Buffer(make([]byte, 1024), 1024*1024)

	var n int
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line != "" {
			n, _ = strconv.Atoi(line)
			break
		}
	}

	grid := make([][]int64, 0, n)
	for len(grid) < n && scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line == "" {
			continue
		}

		fields := strings.Fields(line)
		row := make([]int64, len(fields))
		for i, field := range fields {
			row[i], _ = strconv.ParseInt(field, 10, 64)
		}
		grid = append(grid, row)
	}

	if n == 0 || len(grid) == 0 || len(grid[0]) == 0 {
		return
	}

	m := len(grid[0])
	total := n * m
	const infinity int64 = 1<<63 - 1

	dist := make([]int64, total)
	for i := range dist {
		dist[i] = infinity
	}
	dist[0] = 0

	pq := &PriorityQueue{{time: 0, pos: 0}}
	heap.Init(pq)

	directions := [][2]int{{1, 0}, {-1, 0}, {0, 1}, {0, -1}}

	for pq.Len() > 0 {
		current := heap.Pop(pq).(State)
		if current.time != dist[current.pos] {
			continue
		}
		if current.pos == total-1 {
			fmt.Println(current.time)
			return
		}

		r, c := current.pos/m, current.pos%m
		for _, direction := range directions {
			nr, nc := r+direction[0], c+direction[1]
			if nr < 0 || nr >= n || nc < 0 || nc >= m {
				continue
			}

			startTime := current.time
			if grid[nr][nc] > startTime {
				startTime = grid[nr][nc]
			}
			arrivalTime := startTime + 1
			nextPos := nr*m + nc

			if arrivalTime < dist[nextPos] {
				dist[nextPos] = arrivalTime
				heap.Push(pq, State{time: arrivalTime, pos: nextPos})
			}
		}
	}

	fmt.Println(dist[total-1])
}
