	"strings"
)

type MaxHeap []int

func (h MaxHeap) Len() int           { return len(h) }
func (h MaxHeap) Less(i, j int) bool { return h[i] > h[j] }
func (h MaxHeap) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }

func (h *MaxHeap) Push(x any) {
	*h = append(*h, x.(int))
}

func (h *MaxHeap) Pop() any {
	old := *h
	n := len(old)
	x := old[n-1]
	*h = old[:n-1]
	return x
}

func nextNonEmptyLine(scanner *bufio.Scanner) string {
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line != "" {
			return line
		}
	}
	return ""
}

func parseInts(line string) []int {
	fields := strings.Fields(line)
	values := make([]int, len(fields))
	for i, field := range fields {
		values[i], _ = strconv.Atoi(field)
	}
	return values
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Buffer(make([]byte, 1024), 2*1024*1024)

	numsLine := nextNonEmptyLine(scanner)
	if numsLine == "" {
		return
	}
	nums := parseInts(numsLine)
	n := len(nums)

	queryCountLine := nextNonEmptyLine(scanner)
	if queryCountLine == "" {
		return
	}
	m, _ := strconv.Atoi(strings.Fields(queryCountLine)[0])

	startingAt := make([][]int, n)
	readQueries := 0

	for readQueries < m && scanner.Scan() {
		values := parseInts(scanner.Text())
		for i := 0; i+1 < len(values) && readQueries < m; i += 2 {
			l, r := values[i], values[i+1]
			startingAt[l] = append(startingAt[l], r)
			readQueries++
		}
	}

	active := &MaxHeap{}
	heap.Init(active)

	diff := make([]int, n+1)
	coverage := 0
	used := 0

	for i := 0; i < n; i++ {
		coverage += diff[i]

		for _, r := range startingAt[i] {
			heap.Push(active, r)
		}

		for active.Len() > 0 && (*active)[0] < i {
			heap.Pop(active)
		}

		for coverage < nums[i] {
			for active.Len() > 0 && (*active)[0] < i {
				heap.Pop(active)
			}
			if active.Len() == 0 {
				fmt.Println(-1)
				return
			}

			r := heap.Pop(active).(int)
			coverage++
			used++
			if r+1 < len(diff) {
				diff[r+1]--
			}
		}
	}

	fmt.Println(m - used)
}
