func gcd(a, b int64) int64 {
	for b != 0 {
		a, b = b, a%b
	}
	return a
}

func main() {
	in := bufio.NewReader(os.Stdin)
	var nums []int64

	for {
		var x int64
		if _, err := fmt.Fscan(in, &x); err != nil {
			break
		}
		nums = append(nums, x)
	}

	best := 0

	for left := 0; left < len(nums); left++ {
		product := big.NewInt(1)
		var currentGCD int64
		currentLCM := int64(1)

		for right := left; right < len(nums); right++ {
			x := nums[right]
			product.Mul(product, big.NewInt(x))

			currentGCD = gcd(currentGCD, x)
			currentLCM = currentLCM / gcd(currentLCM, x) * x

			target := big.NewInt(currentGCD * currentLCM)
			if product.Cmp(target) == 0 && right-left+1 > best {
				best = right - left + 1
			}
		}
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, best)
