	fmt.Fscan(in, &k)

	sort.Slice(segments, func(i, j int) bool {
		return segments[i].l < segments[j].l
	})

	prefix := make([]int64, n+1)
	for i, s := range segments {
		prefix[i+1] = prefix[i] + (s.r-s.l+1)*s.c
	}

	sumTo := func(x int64) int64 {
		idx := sort.Search(n, func(i int) bool {
			return segments[i].l > x
		}) - 1

		if idx < 0 {
			return 0
		}

		result := prefix[idx]
		s := segments[idx]
		end := x
		if end > s.r {
			end = s.r
		}
		if end >= s.l {
			result += (end - s.l + 1) * s.c
		}
		return result
	}

	windowSum := func(start int64) int64 {
		return sumTo(start+k-1) - sumTo(start-1)
	}

	var answer int64
	for _, s := range segments {
		boundaries := [2]int64{s.l, s.r + 1}
		for _, boundary := range boundaries {
			v1 := windowSum(boundary)
			if v1 > answer {
				answer = v1
			}

			v2 := windowSum(boundary - k)
			if v2 > answer {
				answer = v2
			}
		}
	}

	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()
	fmt.Fprintln(out, answer)
}
