package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	in := bufio.NewReader(os.Stdin)

	nums := make([]int, 0)
	for {
		var x int
		if _, err := fmt.Fscan(in, &x); err != nil {
			break
		}
		nums = append(nums, x)
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	if len(nums) == 0 {
		fmt.Fprintln(out, 0)
		return
	}

	const (
		maxValue = 300
		maxDiff  = 299
	)

	// exact[v][d] is the longest subsequence ending at value v
	// whose last adjacent difference is exactly d.
	exact := make([][]int, maxValue+1)

	// suffix[v][d] is the maximum exact[v][k] for k >= d.
	suffix := make([][]int, maxValue+1)
	for v := 0; v <= maxValue; v++ {
		exact[v] = make([]int, maxDiff+1)
		suffix[v] = make([]int, maxDiff+2)
	}

	seen := make([]bool, maxValue+1)
	answer := 1

	for _, x := range nums {
		updates := make([]int, maxDiff+1)

		for y := 1; y <= maxValue; y++ {
			if !seen[y] {
				continue
			}

			d := x - y
			if d < 0 {
				d = -d
			}

			length := 2
			if suffix[y][d] > 0 {
				length = suffix[y][d] + 1
			}
			if length > updates[d] {
				updates[d] = length
			}
		}

		for d := 0; d <= maxDiff; d++ {
			if updates[d] > exact[x][d] {
				exact[x][d] = updates[d]
			}
			if updates[d] > answer {
				answer = updates[d]
			}
		}

		best := 0
		for d := maxDiff; d >= 0; d-- {
			if exact[x][d] > best {
				best = exact[x][d]
			}
			suffix[x][d] = best
		}

		seen[x] = true
	}

	fmt.Fprintln(out, answer)
}
