)

type FastScanner struct {
	r *bufio.Reader
}

func (fs *FastScanner) NextInt() int {
	sign, value := 1, 0
	c, err := fs.r.ReadByte()
	for err == nil && (c < '0' || c > '9') && c != '-' {
		c, err = fs.r.ReadByte()
	}
	if c == '-' {
		sign = -1
		c, err = fs.r.ReadByte()
	}
	for err == nil && c >= '0' && c <= '9' {
		value = value*10 + int(c-'0')
		c, err = fs.r.ReadByte()
	}
	return sign * value
}

type Point struct {
	x, y int
}

type Piece struct {
	x, y int
}

func main() {
	in := &FastScanner{r: bufio.NewReaderSize(os.Stdin, 1<<20)}
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	_ = in.NextInt() // W
	_ = in.NextInt() // H

	n := in.NextInt()
	points := make([]Point, n)
	for i := 0; i < n; i++ {
		points[i] = Point{in.NextInt(), in.NextInt()}
	}

	a := in.NextInt()
	verticalCuts := make([]int, a)
	for i := range verticalCuts {
		verticalCuts[i] = in.NextInt()
	}

	b := in.NextInt()
	horizontalCuts := make([]int, b)
	for i := range horizontalCuts {
		horizontalCuts[i] = in.NextInt()
	}

	counts := make(map[Piece]int)
	maxCount := 0

	for _, p := range points {
		xIndex := sort.SearchInts(verticalCuts, p.x)
		yIndex := sort.SearchInts(horizontalCuts, p.y)
		piece := Piece{xIndex, yIndex}
		counts[piece]++
		if counts[piece] > maxCount {
			maxCount = counts[piece]
		}
	}

	totalPieces := int64(a+1) * int64(b+1)
	minCount := 0

	if int64(len(counts)) == totalPieces {
		minCount = n
		for _, count := range counts {
			if count < minCount {
				minCount = count
			}
		}
	}

	fmt.Fprintf(out, "%d %d\n", minCount, maxCount)
}
