package main

import (
	"bufio"
	"container/heap"
	"fmt"
	"os"
	"sort"
)

type Coupon struct {
	limit    int
	discount int
}

type MaxHeap []int

func (h MaxHeap) Len() int           { return len(h) }
func (h MaxHeap) Less(i, j int) bool { return h[i] > h[j] }
func (h MaxHeap) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }

func (h *MaxHeap) Push(x any) {
	*h = append(*h, x.(int))
}

func (h *MaxHeap) Pop() any {
	old := *h
	n := len(old)
	x := old[n-1]
	*h = old[:n-1]
	return x
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var n, m int
	fmt.Fscan(in, &n, &m)

	prices := make([]int, n)
	var total int64
	for i := range prices {
		fmt.Fscan(in, &prices[i])
		total += int64(prices[i])
	}

	coupons := make([]Coupon, m)
	for i := range coupons {
		fmt.Fscan(in, &coupons[i].limit)
	}
	for i := range coupons {
		fmt.Fscan(in, &coupons[i].discount)
	}

	sort.Ints(prices)
	sort.Slice(coupons, func(i, j int) bool {
		return coupons[i].limit < coupons[j].limit
	})

	h := &MaxHeap{}
	heap.Init(h)
	couponIndex := 0

	for _, price := range prices {
		for couponIndex < m && coupons[couponIndex].limit <= price {
			heap.Push(h, coupons[couponIndex].discount)
			couponIndex++
		}
		if h.Len() > 0 {
			total -= int64(heap.Pop(h).(int))
		}
	}

	fmt.Fprintln(out, total)
}
