	"math"
	"os"
)

const maxSkipped = 30

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)

	var n int
	fmt.Fscan(in, &n)

	x := make([]float64, n)
	y := make([]float64, n)
	for i := 0; i < n; i++ {
		fmt.Fscan(in, &x[i], &y[i])
	}

	dp := make([][]float64, n)
	for i := range dp {
		dp[i] = make([]float64, maxSkipped+1)
		for k := range dp[i] {
			dp[i][k] = math.Inf(1)
		}
	}
	dp[0][0] = 0

	for i := 1; i < n; i++ {
		first := i - maxSkipped - 1
		if first < 0 {
			first = 0
		}

		for j := first; j < i; j++ {
			skipped := i - j - 1
			dist := math.Hypot(x[i]-x[j], y[i]-y[j])

			for used := 0; used+skipped <= maxSkipped; used++ {
				if math.IsInf(dp[j][used], 1) {
					continue
				}
				total := used + skipped
				candidate := dp[j][used] + dist
				if candidate < dp[i][total] {
					dp[i][total] = candidate
				}
			}
		}
	}

	answer := math.Inf(1)
	for skipped := 0; skipped <= maxSkipped; skipped++ {
		value := dp[n-1][skipped]
		if skipped > 0 {
			value += math.Ldexp(1, skipped-1)
		}
		if value < answer {
			answer = value
		}
	}

	out := bufio.NewWriterSize(os.Stdout, 1<<16)
	defer out.Flush()
	fmt.Fprintf(out, "%.20f\n", answer)
}
