import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)

	var n int
	fmt.Fscan(in, &n)

	size := n
	if size%2 == 1 {
		size++
	}

	weights := make([][]int64, size)
	for i := range weights {
		weights[i] = make([]int64, size)
	}

	for i := 0; i < n; i++ {
		for j := i + 1; j < n; j++ {
			fmt.Fscan(in, &weights[i][j])
			weights[j][i] = weights[i][j]
		}
	}

	fullMask := (1 << size) - 1
	memo := make([]int64, 1<<size)
	visited := make([]bool, 1<<size)

	var dfs func(mask int) int64
	dfs = func(mask int) int64 {
		if mask == fullMask {
			return 0
		}
		if visited[mask] {
			return memo[mask]
		}
		visited[mask] = true

		first := 0
		for mask&(1<<first) != 0 {
			first++
		}

		var best int64
		for j := first + 1; j < size; j++ {
			if mask&(1<<j) == 0 {
				nextMask := mask | (1 << first) | (1 << j)
				value := weights[first][j] + dfs(nextMask)
				if value > best {
					best = value
				}
			}
		}

		memo[mask] = best
		return best
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, dfs(0))
}
