package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var n int
	fmt.Fscan(in, &n)

	graph := make([][]int, n)
	for i := 0; i < n-1; i++ {
		var u, v int
		fmt.Fscan(in, &u, &v)
		u--
		v--
		graph[u] = append(graph[u], v)
		graph[v] = append(graph[v], u)
	}

	parent := make([]int, n)
	for i := range parent {
		parent[i] = -2
	}
	parent[0] = -1

	order := make([]int, 0, n)
	stack := []int{0}
	for len(stack) > 0 {
		v := stack[len(stack)-1]
		stack = stack[:len(stack)-1]
		order = append(order, v)

		for _, to := range graph[v] {
			if to == parent[v] {
				continue
			}
			parent[to] = v
			stack = append(stack, to)
		}
	}

	subtreeSize := make([]int, n)
	for i := n - 1; i >= 0; i-- {
		v := order[i]
		subtreeSize[v]++
		if parent[v] >= 0 {
			subtreeSize[parent[v]] += subtreeSize[v]
		}
	}

	largestComponent := 0
	for _, child := range graph[0] {
		if subtreeSize[child] > largestComponent {
			largestComponent = subtreeSize[child]
		}
	}

	fmt.Fprintln(out, n-largestComponent)
}
