	var n, m int
	fmt.Fscan(in, &n, &m)

	const inf int32 = 1 << 30

	dist := make([]int32, n*n)
	for i := range dist {
		dist[i] = inf
	}
	for i := 0; i < n; i++ {
		dist[i*n+i] = 0
	}

	for i := 0; i < m; i++ {
		var u, v int
		var w int32
		fmt.Fscan(in, &u, &v, &w)
		u--
		v--
		dist[u*n+v] = w
	}

	// All-pairs shortest paths.
	for k := 0; k < n; k++ {
		for i := 0; i < n; i++ {
			dik := dist[i*n+k]
			if dik == inf {
				continue
			}
			for j := 0; j < n; j++ {
				dkj := dist[k*n+j]
				if dkj == inf {
					continue
				}
				candidate := dik + dkj
				if candidate < dist[i*n+j] {
					dist[i*n+j] = candidate
				}
			}
		}
	}

	size := 1 << n
	dp := make([]int32, size*n)

	for mask := 1; mask < size; mask++ {
		vertices := uint32(mask)
		for vertices != 0 {
			v := bits.TrailingZeros32(vertices)
			vertices &= vertices - 1

			prevMask := mask ^ (1 << v)
			index := mask*n + v
			if prevMask == 0 {
				dp[index] = 0
				continue
			}

			best := inf
			prevVertices := uint32(prevMask)
			base := prevMask * n

			for prevVertices != 0 {
				u := bits.TrailingZeros32(prevVertices)
				prevVertices &= prevVertices - 1

				current := dp[base+u]
				d := dist[u*n+v]
				if current == inf || d == inf {
					continue
				}
				if candidate := current + d; candidate < best {
					best = candidate
				}
			}
			dp[index] = best
		}
	}

	fullMask := size - 1
	answer := inf
	base := fullMask * n
	for v := 0; v < n; v++ {
		if dp[base+v] < answer {
			answer = dp[base+v]
		}
	}

	if answer == inf {
		fmt.Fprintln(out, "No")
	} else {
		fmt.Fprintln(out, answer)
	}
}
