type Node struct {
	value      int
	prev, next *Node
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var n int
	fmt.Fscan(in, &n)

	nodes := make(map[int]*Node, n)
	var head, tail *Node

	for i := 0; i < n; i++ {
		var value int
		fmt.Fscan(in, &value)

		node := &Node{value: value, prev: tail}
		if tail != nil {
			tail.next = node
		} else {
			head = node
		}
		tail = node
		nodes[value] = node
	}

	var q int
	fmt.Fscan(in, &q)

	for ; q > 0; q-- {
		var queryType, x int
		fmt.Fscan(in, &queryType, &x)

		if queryType == 1 {
			var y int
			fmt.Fscan(in, &y)

			current := nodes[x]
			inserted := &Node{
				value: y,
				prev:  current,
				next:  current.next,
			}

			if current.next != nil {
				current.next.prev = inserted
			} else {
				tail = inserted
			}
			current.next = inserted
			nodes[y] = inserted
		} else {
			current := nodes[x]

			if current.prev != nil {
				current.prev.next = current.next
			} else {
				head = current.next
			}

			if current.next != nil {
				current.next.prev = current.prev
			} else {
				tail = current.prev
			}

			delete(nodes, x)
		}
	}

	first := true
	for node := head; node != nil; node = node.next {
		if !first {
			fmt.Fprint(out, " ")
		}
		fmt.Fprint(out, node.value)
		first = false
	}
	fmt.Fprintln(out)
}
