const mod int64 = 998244353

func main() {
	in := bufio.NewReader(os.Stdin)

	var s string
	fmt.Fscan(in, &s)

	n, _ := strconv.ParseUint(s, 10, 64)

	var nMod int64
	for _, c := range s {
		nMod = (nMod*10 + int64(c-'0')) % mod
	}

	base := int64(1)
	for range s {
		base = base * 10 % mod
	}

	// For k copies, keep:
	// power = base^k
	// sum   = 1 + base + ... + base^(k-1)
	resultPower, resultSum := int64(1), int64(0)
	blockPower, blockSum := base, int64(1)

	for n > 0 {
		if n&1 != 0 {
			resultSum = (resultSum + resultPower*blockSum) % mod
			resultPower = resultPower * blockPower % mod
		}

		blockSum = (blockSum + blockPower*blockSum) % mod
		blockPower = blockPower * blockPower % mod
		n >>= 1
	}

	answer := nMod * resultSum % mod

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, answer)
}
