package main

import (
	"bufio"
	"fmt"
	"os"
)

type Edge struct {
	to     int
	weight int64
}

func farthest(start int, graph [][]Edge) (int, int64) {
	type State struct {
		node   int
		parent int
		dist   int64
	}

	stack := make([]State, 0, len(graph))
	stack = append(stack, State{node: start, parent: -1})

	farthestNode := start
	var maxDist int64

	for len(stack) > 0 {
		last := len(stack) - 1
		cur := stack[last]
		stack = stack[:last]

		if cur.dist > maxDist {
			maxDist = cur.dist
			farthestNode = cur.node
		}

		for _, edge := range graph[cur.node] {
			if edge.to != cur.parent {
				stack = append(stack, State{
					node:   edge.to,
					parent: cur.node,
					dist:   cur.dist + edge.weight,
				})
			}
		}
	}

	return farthestNode, maxDist
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var n int
	fmt.Fscan(in, &n)

	graph := make([][]Edge, n)
	var totalLength int64

	for i := 0; i < n-1; i++ {
		var a, b int
		var c int64
		fmt.Fscan(in, &a, &b, &c)
		a--
		b--

		graph[a] = append(graph[a], Edge{to: b, weight: c})
		graph[b] = append(graph[b], Edge{to: a, weight: c})
		totalLength += c
	}

	endpoint, _ := farthest(0, graph)
	_, diameter := farthest(endpoint, graph)

	answer := 2*totalLength - diameter
	fmt.Fprintln(out, answer)
}
