	"os"
)

const mod int64 = 998244353

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)

	var n int
	fmt.Fscan(in, &n)

	a := make([]int64, n)
	for i := range a {
		fmt.Fscan(in, &a[i])
	}

	// dp[i][d][k] is the number of arithmetic subsequences
	// of length k ending at position i with common difference d.
	dp := make([]map[int64][]int64, n)
	for i := range dp {
		dp[i] = make(map[int64][]int64)
	}

	ans := make([]int64, n+1)
	ans[1] = int64(n)

	for i := 0; i < n; i++ {
		for j := 0; j < i; j++ {
			d := a[i] - a[j]

			cur, ok := dp[i][d]
			if !ok {
				cur = make([]int64, n+1)
				dp[i][d] = cur
			}

			// Every pair forms an arithmetic sequence of length 2.
			cur[2]++
			if cur[2] >= mod {
				cur[2] -= mod
			}
			ans[2]++
			if ans[2] >= mod {
				ans[2] -= mod
			}

			if prev, exists := dp[j][d]; exists {
				for length := 2; length < n; length++ {
					if prev[length] == 0 {
						continue
					}
					cur[length+1] += prev[length]
					if cur[length+1] >= mod {
						cur[length+1] -= mod
					}
					ans[length+1] += prev[length]
					if ans[length+1] >= mod {
						ans[length+1] -= mod
					}
				}
			}
		}
	}

	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	for k := 1; k <= n; k++ {
		if k > 1 {
			fmt.Fprint(out, " ")
		}
		fmt.Fprint(out, ans[k])
	}
	fmt.Fprintln(out)
}
