	c, err := fs.r.ReadByte()
	for err == nil && (c < '0' || c > '9') && c != '-' {
		c, err = fs.r.ReadByte()
	}
	if c == '-' {
		sign = -1
		c, err = fs.r.ReadByte()
	}
	for err == nil && c >= '0' && c <= '9' {
		value = value*10 + int(c-'0')
		c, err = fs.r.ReadByte()
	}
	return sign * value
}

func costFrequencies(values []int, d int) []int64 {
	sort.Ints(values)
	n := len(values)
	margin := d / n
	left := values[0] - margin
	right := values[n-1] + margin

	var cost int64
	for _, v := range values {
		diff := v - left
		if diff < 0 {
			diff = -diff
		}
		cost += int64(diff)
	}

	freq := make([]int64, d+1)
	p := 0

	for pos := left; pos <= right; pos++ {
		if cost <= int64(d) {
			freq[int(cost)]++
		}

		for p < n && values[p] <= pos {
			p++
		}
		cost += int64(2*p - n)
	}

	return freq
}

func main() {
	in := &FastScanner{r: bufio.NewReaderSize(os.Stdin, 1<<20)}

	n := in.NextInt()
	d := in.NextInt()

	xs := make([]int, n)
	ys := make([]int, n)
	for i := 0; i < n; i++ {
		xs[i] = in.NextInt()
		ys[i] = in.NextInt()
	}

	fx := costFrequencies(xs, d)
	fy := costFrequencies(ys, d)

	for i := 1; i <= d; i++ {
		fy[i] += fy[i-1]
	}

	var answer int64
	for costX := 0; costX <= d; costX++ {
		answer += fx[costX] * fy[d-costX]
	}

	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	fmt.Fprintln(out, answer)
	out.Flush()
}
