	a int
	b int64
}

type MaxHeap []int64

func (h MaxHeap) Len() int           { return len(h) }
func (h MaxHeap) Less(i, j int) bool { return h[i] > h[j] }
func (h MaxHeap) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }

func (h *MaxHeap) Push(x any) {
	*h = append(*h, x.(int64))
}

func (h *MaxHeap) Pop() any {
	old := *h
	n := len(old)
	x := old[n-1]
	*h = old[:n-1]
	return x
}

func main() {
	in := &FastScanner{r: bufio.NewReaderSize(os.Stdin, 1<<20)}
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	t := in.NextInt()
	for ; t > 0; t-- {
		n, k := in.NextInt(), in.NextInt()

		pairs := make([]Pair, n)
		for i := 0; i < n; i++ {
			pairs[i].a = in.NextInt()
		}
		for i := 0; i < n; i++ {
			pairs[i].b = int64(in.NextInt())
		}

		sort.Slice(pairs, func(i, j int) bool {
			return pairs[i].a < pairs[j].a
		})

		h := &MaxHeap{}
		heap.Init(h)

		var sum int64
		answer := int64(^uint64(0) >> 1)

		for _, p := range pairs {
			heap.Push(h, p.b)
			sum += p.b

			if h.Len() > k {
				sum -= heap.Pop(h).(int64)
			}
			if h.Len() == k {
				value := int64(p.a) * sum
				if value < answer {
					answer = value
				}
			}
		}

		fmt.Fprintln(out, answer)
	}
}
