				id := i*w + j
				dist[id] = 0
				queue = append(queue, id)
				answer++
			}
		}
	}

	dr := [4]int{-1, 1, 0, 0}
	dc := [4]int{0, 0, -1, 1}

	for head := 0; head < len(queue); head++ {
		id := queue[head]
		if dist[id] == d {
			continue
		}

		r, c := id/w, id%w
		for k := 0; k < 4; k++ {
			nr, nc := r+dr[k], c+dc[k]
			if nr < 0 || nr >= h || nc < 0 || nc >= w {
