func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)

	var n int
	fmt.Fscan(in, &n)

	a := make([]uint64, n)
	for i := range a {
		fmt.Fscan(in, &a[i])
	}

	var dfs func(depth int, prefix uint64) int
	dfs = func(depth int, prefix uint64) int {
		var mask uint64
		if depth > 0 {
			mask = (uint64(1) << depth) - 1
		}

		mountains := 0
		undetermined := 0

		for _, v := range a {
			r := (prefix + v) & mask
			if r == 0 {
				undetermined++
				continue
			}

			tz := bits.TrailingZeros64(r)
			if tz+1 >= depth {
				undetermined++
				continue
			}

			// A crease is a mountain fold iff the odd part of its
			// 1-indexed position is congruent to 3 modulo 4.
			if ((r >> (tz + 1)) & 1) == 1 {
				mountains++
			}
		}

		if undetermined == 0 {
			return mountains
		}
		if undetermined == 1 {
			return mountains + 1
		}

		low := dfs(depth+1, prefix)
		high := dfs(depth+1, prefix|(uint64(1)<<depth))
		if low > high {
			return low
		}
		return high
	}

	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()
	fmt.Fprintln(out, dfs(0, 0))
}
