package main

import (
	"bufio"
	"fmt"
	"os"
)

const mod int64 = 998244353

func modPow(a, e int64) int64 {
	result := int64(1)
	for e > 0 {
		if e&1 == 1 {
			result = result * a % mod
		}
		a = a * a % mod
		e >>= 1
	}
	return result
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var n int
	fmt.Fscan(in, &n)

	left := make([]int, n+1)
	right := make([]int, n+1)
	parent := make([]int, n+1)
	stack := make([]int, 0, n)

	for i := 1; i <= n; i++ {
		var a int
		fmt.Fscan(in, &a)

		last := 0
		for len(stack) > 0 && stack[len(stack)-1] != a {
			last = stack[len(stack)-1]
			stack = stack[:len(stack)-1]
		}

		if a > 0 {
			parent[i] = a
			right[a] = i
		}
		if last > 0 {
			parent[last] = i
			left[i] = last
		}

		stack = append(stack, i)
	}

	root := 1
	for root <= n && parent[root] != 0 {
		root++
	}

	order := make([]int, 0, n)
	dfsStack := []int{root}
	for len(dfsStack) > 0 {
		v := dfsStack[len(dfsStack)-1]
		dfsStack = dfsStack[:len(dfsStack)-1]
		order = append(order, v)

		if left[v] != 0 {
			dfsStack = append(dfsStack, left[v])
		}
		if right[v] != 0 {
			dfsStack = append(dfsStack, right[v])
		}
	}

	subtreeSize := make([]int64, n+1)
	product := int64(1)

	for i := len(order) - 1; i >= 0; i-- {
		v := order[i]
		subtreeSize[v] = 1
		if left[v] != 0 {
			subtreeSize[v] += subtreeSize[left[v]]
		}
		if right[v] != 0 {
			subtreeSize[v] += subtreeSize[right[v]]
		}
		product = product * (subtreeSize[v] % mod) % mod
	}

	factorial := int64(1)
	for i := 2; i <= n; i++ {
		factorial = factorial * int64(i) % mod
	}

	answer := factorial * modPow(product, mod-2) % mod
	fmt.Fprintln(out, answer)
}
