package main

import (
	"bufio"
	"fmt"
	"os"
)

const mod int64 = 998244353

func multiply(a, b []int64, limit int) []int64 {
	maxDegree := len(a) + len(b) - 2
	if maxDegree > limit {
		maxDegree = limit
	}
	res := make([]int64, maxDegree+1)

	for i, x := range a {
		if x == 0 || i > limit {
			continue
		}
		maxJ := len(b) - 1
		if i+maxJ > limit {
			maxJ = limit - i
		}
		for j := 0; j <= maxJ; j++ {
			if b[j] != 0 {
				res[i+j] = (res[i+j] + x*b[j]) % mod
			}
		}
	}
	return res
}

func polyPow(base []int64, exp, limit int) []int64 {
	res := []int64{1}
	for exp > 0 {
		if exp&1 == 1 {
			res = multiply(res, base, limit)
		}
		exp >>= 1
		if exp > 0 {
			base = multiply(base, base, limit)
		}
	}
	return res
}

func modPow(a, e int64) int64 {
	res := int64(1)
	for e > 0 {
		if e&1 == 1 {
			res = res * a % mod
		}
		a = a * a % mod
		e >>= 1
	}
	return res
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var N, M, K int
	fmt.Fscan(in, &N, &M, &K)

	X := make([]int, M)
	for i := range X {
		fmt.Fscan(in, &X[i])
	}

	different := 0
	for i := 0; i+1 < M; i++ {
		if X[i] != X[i+1] {
			different++
		}
	}

	q := K - 1
	fixedLength := M - 1 + different
	minLength := M*q + fixedLength
	if minLength > N {
		fmt.Fprintln(out, 0)
		return
	}

	remaining := N - minLength

	// onto[length] is the number of words of this length over q symbols
	// in which every symbol occurs.
	onto := make([]int64, q+remaining+1)
	dp := make([]int64, q+1)
	dp[0] = 1

	for length := 1; length <= q+remaining; length++ {
		next := make([]int64, q+1)
		for used := 0; used <= q; used++ {
			if dp[used] == 0 {
				continue
			}
			next[used] = (next[used] + dp[used]*int64(used)) % mod
			if used < q {
				next[used+1] = (next[used+1] +
					dp[used]*int64(q-used)) % mod
			}
		}
		dp = next
		onto[length] = dp[q]
	}

	// Remove the mandatory minimum degree q from each onto-word.
	g := make([]int64, remaining+1)
	for r := 0; r <= remaining; r++ {
		g[r] = onto[q+r]
	}

	powered := polyPow(g, M, remaining)

	if different == 0 {
		fmt.Fprintln(out, powered[remaining])
		return
	}

	// Coefficients of (1-(K-2)t)^(-different).
	geom := make([]int64, remaining+1)
	geom[0] = 1
	a := int64(K - 2)

	for s := 1; s <= remaining; s++ {
		numerator := int64(different + s - 1)
		invS := modPow(int64(s), mod-2)
		geom[s] = geom[s-1] * numerator % mod
		geom[s] = geom[s] * invS % mod
		geom[s] = geom[s] * a % mod
	}

	var answer int64
	for s := 0; s <= remaining; s++ {
		if remaining-s < len(powered) {
			answer = (answer + geom[s]*powered[remaining-s]) % mod
		}
	}

	fmt.Fprintln(out, answer)
}
