package main

import (
	"bufio"
	"fmt"
	"os"
)

const mod int64 = 998244353

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)

	var n, k int
	var s string
	fmt.Fscan(in, &n, &k)
	fmt.Fscan(in, &s)

	base := n + 2
	pow := [4]int{1, base, base * base, base * base * base}

	// The key encodes the visit counts of the four quotient parity states.
	// The array stores counts of assignments for each current state.
	dp := make(map[int][4]int64)
	dp[1] = [4]int64{1, 0, 0, 0}

	for i := 0; i < n; i++ {
		var deltas [3]int
		m := 1
		switch s[i] {
		case 'A':
			deltas[0] = 1
		case 'B':
			deltas[0] = 2
		case 'C':
			deltas[0] = 3
		default:
			deltas = [3]int{1, 2, 3}
			m = 3
		}

		next := make(map[int][4]int64, len(dp)*3)
		for key, ways := range dp {
			for state, value := range ways {
				if value == 0 {
					continue
				}
				for j := 0; j < m; j++ {
					nextState := state ^ deltas[j]
					nextKey := key + pow[nextState]

					arr := next[nextKey]
					arr[nextState] += value
					if arr[nextState] >= mod {
						arr[nextState] -= mod
					}
					next[nextKey] = arr
				}
			}
		}
		dp = next
	}

	var answer int64
	for key, ways := range dp {
		x := key
		goodCount := 0
		for i := 0; i < 4; i++ {
			count := x % base
			x /= base
			goodCount += count * (count - 1) / 2
		}

		if goodCount >= k {
			for _, value := range ways {
				answer += value
				if answer >= mod {
					answer -= mod
				}
			}
		}
	}

	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()
	fmt.Fprintln(out, answer)
}
